class Solution {
public:
    int countRangeSum(vector<int>& nums, int lower, int upper) {
        int n = nums.size();
        vector<long long> prefix(n + 1, 0);
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];
        vector<long long> temp(n + 1);
        return mergeSort(prefix, temp, 0, n, lower, upper);
    }
private:
    int mergeSort(vector<long long>& arr, vector<long long>& temp, int lo, int hi, int lower, int upper) {
        if (lo >= hi) return 0;
        int mid = lo + (hi - lo) / 2;
        int count = mergeSort(arr, temp, lo, mid, lower, upper)
                 + mergeSort(arr, temp, mid + 1, hi, lower, upper);
        int p = mid + 1, q = mid + 1;
        for (int i = lo; i <= mid; i++) {
            long long l = arr[i] + lower;
            long long r = arr[i] + upper;
            while (p <= hi && arr[p] < l) p++;
            while (q <= hi && arr[q] <= r) q++;
            count += q - p;
        }
        int a = lo, b = mid + 1, k = lo;
        while (a <= mid && b <= hi) {
            if (arr[a] <= arr[b]) temp[k++] = arr[a++];
            else temp[k++] = arr[b++];
        }
        while (a <= mid) temp[k++] = arr[a++];
        while (b <= hi) temp[k++] = arr[b++];
        for (int i = lo; i <= hi; i++) arr[i] = temp[i];
        return count;
    }
};
